const types={V:'void',Z:'jboolean',B:'jbyte',C:'jchar',S:'jshort',I:'jint',J:'jlong',F:'jfloat',D:'jdouble'};function jt(d){if(types[d])return types[d];if(d[0]=='[')return d.length==2&&types[d[1]]?types[d[1]]+'Array':'jobjectArray';return d=='Ljava/lang/String;'?'jstring':d=='Ljava/lang/Class;'?'jclass':'jobject'}
