put('catalog.js',`const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const q=document.getElementById('query').value.toLowerCase(),g=document.getElementById('group').value;const a=window.APK_CLASSES.filter(c=>(!g||c.g===g)&&(!q||(c.n+' '+c.s).toLowerCase().includes(q)));document.getElementById('count').textContent=a.length+' clase';document.getElementById('results').innerHTML='<table><tr><th>Clasă</th><th>DEX</th><th>Metode</th><th>Câmpuri</th><th>API</th></tr>'+a.slice(0,100).map(c=>'<tr><td>'+e(c.n)+'</td><td>'+e(c.d)+'</td><td>'+e(c.m)+'</td><td>'+e(c.f)+'</td><td><a href="api/'+encodeURIComponent(c.g)+'.txt">'+e(c.g)+'</a></td></tr>').join('')+'</table>'}document.getElementById('query').addEventListener('input',render);document.getElementById('group').addEventListener('change',render);render();`);
const errors=[];let checked=0;for(const f of read('inventar/apk-files.json')){const path=p.join(root,'extras/apk',f.file);if(!fs.existsSync(path)){errors.push('missing '+f.file);continue;}const b=fs.readFileSync(path);if(b.length!==f.bytes||crypto.createHash('sha256').update(b).digest('hex')!==f.sha256)errors.push('hash '+f.file);checked++;}
const sm=read('reconstituit/smali/smali-summary.json');if(sm.exported!==summary.classes||sm.failed)errors.push('smali counts');
for(const match of fs.readFileSync(p.join(root,'INDEX.html'),'utf8').matchAll(/(?:href|src)="([^"]+)"/g)){const f=match[1].replaceAll('&amp;','&');if(f==='inventar/validation.json')continue;if(!fs.existsSync(p.resolve(root,f)))errors.push('link '+f);}
put('inventar/validation.json',JSON.stringify({date:new Date().toISOString(),originalFilesSha256Checked:checked,smaliClasses:sm.exported,errors,browserVisualCheck:false,hardwareCheck:false},null,2));console.log(JSON.stringify({checked,smali:sm,errors}));
